function rowsOf(nodeName) {
  const root = $(nodeName).first()?.json ?? {};
  if (Array.isArray(root)) return root;
  if (Array.isArray(root.data)) return root.data;
  if (Array.isArray(root.items)) return root.items;
  if (Array.isArray(root.results)) return root.results;
  return [];
}
function contentId(row) {
  return String(row.content_id ?? row.contentId ?? row.video_id ?? row.videoId ?? row.contentID ?? row.id ?? '');
}
function competitorId(row) {
  return row.competitor_id ?? row.competitorId ?? row.competitor?.id ?? null;
}
function competitorName(row) {
  return String(row.competitor_name ?? row.competitorName ?? row.name ?? row.competitor?.name ?? 'Unknown competitor');
}
function toNum(v) {
  const n = Number(v ?? 0);
  return Number.isFinite(n) ? n : 0;
}

const perf=rowsOf('02 - Get Competitor KPI Data');
const trends=rowsOf('03 - Get Trends');
const monitoring=rowsOf('04 - Get Alerts and Monitoring Data');
const opportunities=rowsOf('05 - Get Opportunities');
const risks=rowsOf('06 - Get Risks');
const strategies=rowsOf('07 - Get Strategies');
const analyses=rowsOf('08 - Get Content Analysis');
const groups=new Map();
for(const p of perf){const key=String(competitorId(p)??competitorName(p));if(!groups.has(key))groups.set(key,{competitor_id:competitorId(p),competitor_name:competitorName(p),platform:p.platform??'unknown',content_count:0,total_views:0,total_likes:0,total_comments:0});const g=groups.get(key);g.content_count++;g.total_views+=toNum(p.views);g.total_likes+=toNum(p.likes);g.total_comments+=toNum(p.comments);}
const kpis=[...groups.values()].map(g=>({...g,engagement_rate:g.total_views?Number(((g.total_likes+g.total_comments)/g.total_views*100).toFixed(2)):0}));
const alerts=[];
for(const row of monitoring){const ms=Array.isArray(row.metrics)?row.metrics:[];const cur=ms[0]??{},prev=ms[1]??{};const pct=(a,b)=>toNum(b)>0?Number(((toNum(a)-toNum(b))/toNum(b)*100).toFixed(2)):0;const v=pct(cur.views,prev.views),l=pct(cur.likes,prev.likes),c=pct(cur.comments,prev.comments);if(v>=1||l>=1||c>=1)alerts.push({competitor:competitorName(row),content_id:row.contentId??row.content_id??null,views_growth_rate:v,likes_growth_rate:l,comments_growth_rate:c});}
const topics=new Map();for(const a of analyses){const t=String(a.topic??a.category??'Unknown');topics.set(t,(topics.get(t)||0)+1);}
const now=new Date();const start=new Date(now.getTime()-7*24*60*60*1000);
const period={from:start.toISOString().slice(0,10),to:now.toISOString().slice(0,10)};
const context={period,competitor_overview:kpis.map(k=>({competitor_id:k.competitor_id,competitor_name:k.competitor_name,platform:k.platform,content_count:k.content_count})),competitor_performance:kpis,trends:trends.slice(0,25),alerts:alerts.slice(0,30),opportunities:opportunities.slice(0,20),risks:risks.slice(0,20),strategies:strategies.slice(0,20),content_topics:[...topics.entries()].sort((a,b)=>b[1]-a[1]).slice(0,20).map(([topic,count])=>({topic,count})),data_counts:{competitors:kpis.length,contents:perf.length,trends:trends.length,alerts:alerts.length,opportunities:opportunities.length,risks:risks.length,strategies:strategies.length,content_analyses:analyses.length}};
return [{json:{context,ai_prompt:`You are an executive analyst producing an evidence-based social media competitor strategy report. Use ONLY the provided context. Do not invent data or claim records exist if a count is zero. Return one valid JSON object with keys: executive_summary (string), competitor_overview (array), competitor_performance (array), top_trends (array), alerts (array), opportunities (array), risks (array), strategic_recommendations (array), conclusion (string), evidence_summary (array). Include period ${period.from} to ${period.to}. The report should be readable and concise, state limitations when data is missing, and connect recommendations to supplied evidence.\nCONTEXT:\n${JSON.stringify(context).slice(0,20000)}`}}];

const r = $input.first().json;

// Lấy nội dung AI trả về, dù là văn bản hay cấu trúc object.
const raw =
  r.content?.parts?.[0]?.text ??
  r.output?.[0]?.content?.[0]?.text ??
  r.output?.[0]?.content?.text ??
  r.text ??
  r.message?.content ??
  r.response ??
  r.content ??
  r.output;

let aiText;

if (typeof raw === 'string') {
  aiText = raw.trim();
} else if (raw && typeof raw === 'object') {
  aiText = JSON.stringify(raw, null, 2);
} else {
  throw new Error('Node 10 không trả về nội dung báo cáo.');
}

if (!aiText) {
  throw new Error('Nội dung báo cáo từ AI đang trống.');
}

const context = $('09 - Build Report Context').first().json.context;
const period = context.period;

const report = {
  report_type: 'strategic',
  title: `AI Competitive Analysis Report (${period.from} - ${period.to})`,
  period,

  // Giữ nguyên toàn bộ văn bản do AI tạo.
  executive_summary: aiText,

  // Giữ dữ liệu gốc từ backend.
  competitor_overview: context.competitor_overview,
  competitor_performance: context.competitor_performance,
  top_trends: context.trends,
  alerts: context.alerts,
  opportunities: context.opportunities,
  risks: context.risks,
  strategic_recommendations: context.strategies,

  conclusion: '',
  evidence_summary: [],
  data_counts: context.data_counts,
  generated_at: new Date().toISOString()
};

return [{ json: report }];
